create table "library"."push_abandoned_onboarding" (
    "id" bigint generated by default as identity not null,
    "title" text,
    "body" text not null,
    "question_id" text,
    "question_response" text
);


alter table "library"."push_abandoned_onboarding" enable row level security;

CREATE UNIQUE INDEX push_abandoned_onboarding_pkey ON library.push_abandoned_onboarding USING btree (id);

alter table "library"."push_abandoned_onboarding" add constraint "push_abandoned_onboarding_pkey" PRIMARY KEY using index "push_abandoned_onboarding_pkey";

grant delete on table "library"."push_abandoned_onboarding" to "anon";

grant insert on table "library"."push_abandoned_onboarding" to "anon";

grant references on table "library"."push_abandoned_onboarding" to "anon";

grant select on table "library"."push_abandoned_onboarding" to "anon";

grant trigger on table "library"."push_abandoned_onboarding" to "anon";

grant truncate on table "library"."push_abandoned_onboarding" to "anon";

grant update on table "library"."push_abandoned_onboarding" to "anon";

grant delete on table "library"."push_abandoned_onboarding" to "authenticated";

grant insert on table "library"."push_abandoned_onboarding" to "authenticated";

grant references on table "library"."push_abandoned_onboarding" to "authenticated";

grant select on table "library"."push_abandoned_onboarding" to "authenticated";

grant trigger on table "library"."push_abandoned_onboarding" to "authenticated";

grant truncate on table "library"."push_abandoned_onboarding" to "authenticated";

grant update on table "library"."push_abandoned_onboarding" to "authenticated";

grant delete on table "library"."push_abandoned_onboarding" to "service_role";

grant insert on table "library"."push_abandoned_onboarding" to "service_role";

grant references on table "library"."push_abandoned_onboarding" to "service_role";

grant select on table "library"."push_abandoned_onboarding" to "service_role";

grant trigger on table "library"."push_abandoned_onboarding" to "service_role";

grant truncate on table "library"."push_abandoned_onboarding" to "service_role";

grant update on table "library"."push_abandoned_onboarding" to "service_role";

create policy "Access to all"
on "library"."push_abandoned_onboarding"
as permissive
for select
to public
using (true);



