    "title" text not null,
    "body" text not null
);


alter table "payment"."trial_notifications" enable row level security;

CREATE UNIQUE INDEX trial_notifications_pkey ON payment.trial_notifications USING btree (id);

alter table "payment"."trial_notifications" add constraint "trial_notifications_pkey" PRIMARY KEY using index "trial_notifications_pkey";

grant delete on table "payment"."trial_notifications" to "anon";

