grant references on table "payment"."trial_notifications" to "authenticated";

grant select on table "payment"."trial_notifications" to "authenticated";

grant trigger on table "payment"."trial_notifications" to "authenticated";

grant truncate on table "payment"."trial_notifications" to "authenticated";

